{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 public ACLs are not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "CRITICAL",
      "explanation": "The omitted block_public_acls setting defaults to false, allowing public ACLs to be applied to the associated S3 bucket."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "S3 public bucket policies are not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The omitted block_public_policy setting defaults to false, allowing a public bucket policy to be attached."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "S3 public ACLs are not ignored",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The omitted ignore_public_acls setting defaults to false, so existing or subsequently accepted public ACLs may remain effective."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "S3 public bucket access is not restricted",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "restrict_public_buckets is explicitly false, so access granted through a public bucket policy is not restricted."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket                  = aws_s3_bucket.api_docs.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Enabled all four S3 public access block controls to prevent public ACLs and public bucket policies from exposing the associated bucket."
}
